/* UK Study Plus · explanations for questions that had none, so every answer pop-up teaches the correct understanding.
   Keyed by subject/topic and the exact question text; only fills an explanation that is empty (never overwrites one). */
(function(U){
const X = {
"y10biology/ecology": {
 "What is a habitat?": "A habitat is the place where an organism lives, such as a pond, a forest floor or a coral reef. It provides the food, shelter and conditions the organism needs.",
 "How does deforestation increase CO₂?": "Fewer trees means less photosynthesis, so less CO₂ is removed from the air. Burning the trees, or letting them decompose, also releases the carbon stored in the wood as CO₂." },
"y10biology/resources": {
 "What do pesticides do?": "Pesticides kill pests (insects, fungi, weeds) that damage or eat crops, so yields increase. Drawbacks: they can kill harmless species and build up in food chains.",
 "Which bacterium makes yoghurt?": "Lactobacillus bacteria ferment lactose (milk sugar) into lactic acid. The acid makes the milk proteins thicken and gives yoghurt its sour taste.",
 "Why are fermenters stirred?": "Stirring (paddles) spreads nutrients, oxygen and heat evenly, so every microorganism has what it needs and no part of the fermenter overheats.",
 "What is a vector in genetic modification?": "A vector carries the useful gene into the host cell. Plasmids (small rings of bacterial DNA) and viruses are used as vectors.",
 "Why add paraffin heaters to glasshouses?": "Burning paraffin releases heat AND carbon dioxide. Both are limiting factors for photosynthesis, so crops grow faster." },
"y10chemistry/rates": {
 "What does a catalyst do?": "A catalyst speeds up a reaction without being chemically changed or used up, so it can be used again. It works by providing a route with a lower activation energy.",
 "Why does higher concentration increase rate?": "More reactant particles in the same volume means they collide more often, so there are more successful collisions per second.",
 "What does ⇌ mean?": "⇌ shows a reversible reaction: the products can react to form the reactants again. In a closed system it reaches dynamic equilibrium.",
 "Why might a reaction graph level off?": "The line goes flat when the reaction stops, because one reactant (the limiting reactant) has been completely used up.",
 "How does a catalyst affect the energy profile?": "On an energy profile, the catalysed route has a lower peak: the activation energy is lower. The overall energy change (ΔH) stays the same.",
 "Increasing gas pressure speeds up a gas reaction because…": "Higher pressure squeezes the same number of gas particles into a smaller volume, so they are closer together and collide more frequently." },
"y10chemistry/organic": {
 "What does a hydrocarbon contain?": "A hydrocarbon is a compound made of hydrogen and carbon atoms ONLY, e.g. methane CH₄. Alcohols are not hydrocarbons because they contain oxygen.",
 "What is the general formula of alkanes?": "Alkanes have the general formula CₙH₂ₙ₊₂. For n = 3 (propane): C₃H₈.",
 "What does bromine water do with an alkene?": "Alkenes have a C=C double bond, which reacts with bromine, so orange bromine water turns colourless. Alkanes leave it orange.",
 "Why is incomplete combustion dangerous?": "With too little oxygen, carbon monoxide (CO) forms. It is colourless and odourless and stops your blood carrying oxygen, so it can kill.",
 "Why do longer hydrocarbons have higher boiling points?": "Bigger molecules have stronger intermolecular forces between them, so more energy is needed to separate them.",
 "What are the conditions for catalytic cracking?": "Cracking breaks long alkanes into shorter alkanes and alkenes. Catalytic cracking uses about 600–700 °C and a silica or alumina catalyst.",
 "Why are addition polymers hard to dispose of?": "Addition polymers are inert and non-biodegradable, so they last for hundreds of years in landfill, and burning them can release toxic gases." },
"y10physics/waves": {
 "Why are optical fibres used in endoscopes?": "Light hits the inside of the fibre at more than the critical angle, so it is totally internally reflected all the way along, carrying an image from inside the body.",
 "What is the speed of EM waves in a vacuum?": "All electromagnetic waves travel at 3 × 10⁸ m/s (300 000 000 m/s) in a vacuum, whatever their frequency.",
 "Which EM wave is used for thermal imaging?": "Warm objects give off more infrared radiation, so infrared cameras show temperature differences, even in the dark.",
 "What is a danger of ultraviolet?": "UV has more energy than visible light. It can damage skin cells and eyes and cause skin cancer, which is why we use sun cream and sunglasses." },
"y10physics/magnetism": {
 "What happens when two north poles are brought together?": "Like poles repel and unlike poles attract, so two north poles push each other away.",
 "How can you increase the force on a wire in a motor?": "The motor-effect force F = BIL, so increase the current (I), use a stronger magnet (B) or a longer length of wire in the field (more turns of coil).",
 "Why does a transformer only work with a.c.?": "Only a changing current makes a changing magnetic field in the iron core, and only a changing field induces a voltage in the secondary coil. Steady d.c. induces nothing.",
 "Which material is magnetically soft?": "Iron is magnetically soft: it magnetises easily and loses its magnetism quickly, which is why it is used in electromagnets and transformer cores. Steel is magnetically hard.",
 "What is induced when a magnet moves into a coil?": "Moving a magnet into a coil changes the magnetic field through it, which induces a voltage. If the coil is part of a complete circuit, a current flows.",
 "How does a loudspeaker work?": "Alternating current in the coil sits in a permanent magnet's field, so the motor effect pushes the coil back and forth. The cone vibrates and makes sound waves." },
"y10physics/astro": {
 "Which force keeps planets in orbit?": "Gravity from the Sun pulls the planets towards it. Because they are moving sideways, the pull bends their path into an orbit instead of making them fall in.",
 "Which colour of star is hottest?": "Star colour shows surface temperature: red stars are coolest (about 3000 K), yellow ones like the Sun are medium, and blue-white stars are hottest.",
 "What is the name of our galaxy?": "The Solar System is in the Milky Way, a spiral galaxy of over 100 billion stars.",
 "What forms after a supernova of a very massive star?": "After a supernova, the core of a massive star collapses into a neutron star or, for the most massive stars, a black hole.",
 "On an HR diagram, where are main-sequence stars?": "On a Hertzsprung–Russell diagram, main-sequence stars form a diagonal band from hot, bright stars (top left) to cool, dim stars (bottom right)." },
"y10english/summary": {
 "What is the maximum length for the summary?": "The Cambridge 0500 summary should be no more than about 120 words. Going far over loses marks for concision, so plan and select your points.",
 "Which should NOT be in a summary?": "A summary reports the writer's ideas in your own words. Leave out your opinions, extra examples, quotations and repetition.",
 "'The old harbour lay silent, its boats rotting.' What can you infer?": "'Silent' and 'rotting' suggest that nobody uses or cares for the harbour any more, so we infer it is abandoned and in decline.",
 "How do you answer 'Explain, using your own words, what the writer means by…'?": "Show that you understand by rephrasing the meaning in your own words. Copying the writer's key words gives no credit.",
 "What does 'infer' mean?": "To infer is to work out meaning that is suggested, not stated, by using clues in the text: 'reading between the lines'.",
 "Which text is the summary based on?": "The question names one text (usually Text B). Using points from the wrong text earns no marks, so check the instruction.",
 "What gets the best marks for 'own words'?": "Accurate paraphrase keeps the original meaning but changes the vocabulary and sentence structure. Lifting phrases loses marks.",
 "When should you plan a summary?": "Plan first: select the relevant points, then group similar ones, so your summary is organised and fits the word limit." },
"y10english/directed": {
 "What should an article usually start with?": "An article starts with a headline (and often a subheading) to grab the reader's attention and show the topic.",
 "What does 'register' mean?": "Register is how formal or informal your language is. Match it to the audience: formal for a headteacher, more relaxed for classmates.",
 "Which is the best way to use the texts?": "Don't copy the texts. Select their ideas, develop them and comment on them in your own words to show understanding.",
 "A speech to classmates should…": "Speeches address the audience directly ('you', 'we') and use spoken techniques such as rhetorical questions, repetition and a strong ending.",
 "What does 'evaluate' mean in directed writing?": "To evaluate is to judge how convincing or reliable the arguments in the texts are, not just to repeat them.",
 "Which sentence evaluates a text?": "This sentence makes a judgement (the claim is weakened) and gives a reason (it relies on one person's experience). That is evaluation.",
 "Why include a counter-argument?": "Mentioning and answering the other side shows balanced, mature thinking and makes your own viewpoint more persuasive.",
 "Who is the audience in a letter to a newspaper?": "You write to the editor, but the letter is published, so the real audience is the newspaper's readers. Use a formal register.",
 "What is a report's typical feature?": "Reports are organised with subheadings and use a formal, objective tone, often ending with recommendations.",
 "What makes a directed-writing answer high level?": "Top answers develop and evaluate ideas from the texts, link them together and build a clear, consistent viewpoint for the audience." },
"y10history/usa": {
 "Who was arrested for refusing to give up her bus seat?": "Rosa Parks was arrested in Montgomery, Alabama, in December 1955. It led to the Montgomery Bus Boycott, which lasted 381 days.",
 "What did the Civil Rights Act (1964) do?": "The Civil Rights Act banned segregation in public places and discrimination in employment based on race, colour, religion, sex or national origin.",
 "What happened at Little Rock in 1957?": "Nine Black students (the Little Rock Nine) were blocked from Central High School. President Eisenhower sent federal troops to protect them.",
 "What were the Freedom Rides (1961)?": "Mixed groups of Black and white activists rode interstate buses into the South to test whether segregated terminals were being desegregated. They faced violent attacks.",
 "Who was a leading figure in the Black Power movement?": "Malcolm X argued for Black pride and self-defence. Stokely Carmichael popularised the slogan 'Black Power' in 1966.",
 "Why did Nixon resign in 1974?": "The Watergate scandal: Nixon's staff broke into Democratic headquarters and Nixon helped cover it up. Facing impeachment, he resigned.",
 "What was McCarthyism?": "In the early 1950s Senator Joseph McCarthy accused many Americans of being communists, often with no evidence, ruining careers.",
 "Why did some young Black Americans turn to Black Power?": "Many felt that peaceful protest was too slow while poverty, discrimination and violence continued, especially in northern cities.",
 "What did Roe v Wade (1973) decide?": "The Supreme Court ruled that women had a constitutional right to abortion. It was a key result of the women's movement (later overturned in 2022)." },
"y10history/ww1": {
 "Who was assassinated on 28 June 1914?": "Archduke Franz Ferdinand, heir to Austria-Hungary, was shot in Sarajevo by Gavrilo Princip. It triggered the July Crisis.",
 "Which countries formed the Triple Entente?": "Britain, France and Russia formed the Triple Entente. The Triple Alliance was Germany, Austria-Hungary and Italy.",
 "What was the Schlieffen Plan?": "Germany planned to defeat France quickly by marching through Belgium, then turn east to fight Russia. Invading Belgium brought Britain into the war.",
 "Which battle in 1916 saw about 57 000 British casualties on its first day?": "On 1 July 1916, the first day of the Battle of the Somme, Britain suffered about 57 000 casualties, including about 19 000 dead.",
 "Why is Jutland (1916) debated?": "Britain lost more ships and men, so Germany claimed victory, but the German fleet stayed in port for the rest of the war, so Britain kept control of the North Sea.",
 "Why did the USA join the war in 1917?": "Germany restarted unrestricted submarine warfare, sinking US ships, and the Zimmermann Telegram showed Germany asking Mexico to attack the USA.",
 "What was 'no man's land'?": "No man's land was the ground between enemy trenches, full of barbed wire and shell craters, where soldiers were exposed to fire.",
 "What happened at Gallipoli (1915)?": "Allied troops (including ANZACs) landed in Turkey to open a route to Russia and knock Turkey out of the war. It failed, with heavy losses.",
 "Why was the Battle of the Marne (1914) a turning point?": "The Allies stopped the German advance near Paris, so the Schlieffen Plan failed. Both sides dug in and trench stalemate began.",
 "Which new weapon was first used at the Somme?": "British tanks were first used in September 1916 during the Somme. They were slow and unreliable at first but improved later." },
"y10history/medicine": {
 "Who published germ theory in 1861?": "Louis Pasteur showed that microbes in the air cause decay, which led to germ theory: germs cause disease.",
 "Who introduced carbolic acid antiseptic?": "Joseph Lister used carbolic acid spray and dressings from 1867, greatly reducing infection after surgery.",
 "In which year was the NHS founded?": "The National Health Service began on 5 July 1948, giving free healthcare to everyone at the point of use.",
 "How did WWI help surgery?": "Huge numbers of wounds led to advances in mobile X-ray units, blood storage (so transfusions could be done later) and plastic surgery.",
 "Why was penicillin not mass-produced until the 1940s?": "Fleming found penicillin in 1928 but couldn't purify it. Florey and Chain did, and WWII created the demand and US funding for mass production.",
 "Why were the Liberal reforms (1906–11) significant?": "For the first time the government took responsibility for welfare: free school meals, old-age pensions and National Insurance for sick pay.",
 "What did miasma theory blame for disease?": "Miasma theory said disease was caused by bad air from rotting matter. It was replaced by germ theory.",
 "What did Koch do?": "Robert Koch identified the specific bacteria that cause specific diseases, such as TB (1882) and cholera (1883), and developed ways to stain and grow them.",
 "Why did the Public Health Act of 1875 matter more than 1848?": "The 1848 Act was voluntary, so few towns acted. The 1875 Act was compulsory: councils had to provide clean water, sewers and medical officers.",
 "Who led the creation of the NHS?": "Aneurin Bevan, Minister of Health, set up the NHS in 1948, building on the Beveridge Report (1942)." },
"y10geography/economic": {
 "Which is a primary activity?": "Primary activities take raw materials from the land or sea: farming, fishing, mining and forestry.",
 "Which is a renewable energy source?": "Wind will not run out because it is constantly replenished. Coal, oil and gas are finite (non-renewable).",
 "Which sector is software research?": "The quaternary sector is knowledge-based: research and development, IT and consultancy.",
 "What does the Clark–Fisher model show?": "It shows how employment shifts as a country develops: from mostly primary, to secondary (manufacturing), to mostly tertiary and quaternary.",
 "What is informal employment?": "Informal work is not taxed, registered or protected by law, such as street vending. It is common in developing countries.",
 "Why might a factory locate near a port?": "A port reduces transport costs for importing heavy raw materials and exporting finished goods.",
 "What is energy security?": "A country is energy secure when it has reliable access to enough affordable energy, without depending too much on unstable supplies.",
 "Why does energy demand rise in NEEs?": "In newly emerging economies, industrialisation, urbanisation and rising living standards (more cars, appliances and air conditioning) all increase energy use.",
 "Which is a tertiary job?": "Tertiary jobs provide services, such as nursing, teaching and retail.",
 "What is deindustrialisation?": "Deindustrialisation is the decline of manufacturing in an area, often because factories move abroad where costs are lower.",
 "Name a drawback of hydroelectric power.": "Building a dam floods valleys, which displaces people and destroys habitats, and it is expensive to build.",
 "How can countries reduce energy demand?": "Use energy more efficiently: insulate buildings, use efficient appliances and LED lights, and encourage public transport." },
"y10geography/development": {
 "Which indicator measures infant deaths?": "Infant mortality rate = the number of babies who die before their first birthday per 1000 live births. Lower means more developed.",
 "What is a bottom-up project?": "Bottom-up projects are small-scale and led by local communities, often with NGOs, so they meet local needs (e.g. a village well).",
 "What does HDI combine?": "The Human Development Index combines income (GNI per capita), health (life expectancy) and education (years of schooling).",
 "What is multilateral aid?": "Multilateral aid is given through international organisations such as the World Bank or UN, which pool money from many countries.",
 "How can debt slow development?": "Money spent repaying loans and interest cannot be spent on schools, hospitals or infrastructure.",
 "Why might a top-down project fail local people?": "Large government-led projects may not meet local needs, may displace people (e.g. dams) and the benefits may go to cities or companies.",
 "What is sustainable development?": "Development that meets people's needs today without damaging the ability of future generations to meet theirs.",
 "Why is GDP per capita a limited indicator?": "It is an average, so it hides inequality between rich and poor and says nothing about health, education or quality of life.",
 "What is literacy rate?": "The literacy rate is the percentage of adults who can read and write. It is a key education indicator.",
 "What is an NGO?": "A non-governmental organisation, such as Oxfam or WaterAid, is a charity independent of government.",
 "How can fair trade help development?": "Fairtrade guarantees farmers a minimum price plus a premium to invest in community projects such as schools and clean water.",
 "Why can conflict slow development?": "War destroys infrastructure, forces people from their homes and diverts money from services to the military." },
"y10computing/impact": {
 "What is e-waste?": "E-waste is discarded electronic equipment. It contains toxic metals such as lead and mercury, but also valuable materials that can be recovered.",
 "What is open-source software?": "Open-source software makes its source code public, so anyone can view, modify and share it (e.g. Linux, Python).",
 "Which law protects creators' work?": "Copyright law protects original work such as software, music and images from being copied without permission.",
 "Why do data centres raise environmental concerns?": "They need huge amounts of electricity to run servers and to cool them, which can increase carbon emissions and water use.",
 "What is algorithmic bias?": "If an AI is trained on biased data, its decisions can be unfair to some groups, for example in hiring or face recognition.",
 "What is the Internet of Things?": "Everyday devices (smart speakers, thermostats, fridges) connected to the internet so they can send and receive data.",
 "Why might proprietary software be chosen over open source?": "Proprietary software usually comes with official support, warranties, training and regular updates.",
 "Who should be accountable when an AI makes a harmful decision?": "There is no single agreed answer: responsibility is shared between developers, the organisations that deploy it and regulators. Exam answers should weigh up these views.",
 "How can e-waste be reduced?": "Repair devices, reuse or donate them, and recycle them properly so materials are recovered safely.",
 "What is a software licence?": "A licence is a legal agreement that sets how software may be used, copied or shared.",
 "What is a code review?": "Other programmers check code for bugs, security vulnerabilities and readability before it is released.",
 "What is quantum computing's potential impact?": "Quantum computers could solve some problems much faster than normal computers, which might break current encryption methods." },
"y10ict/systems": {
 "Which memory is volatile?": "RAM is volatile: it loses its contents when the power is turned off. ROM is non-volatile.",
 "Which device reads the magnetic ink on cheques?": "MICR (magnetic ink character recognition) reads the special magnetic ink numbers on cheques quickly and accurately.",
 "Which is system software?": "System software runs the computer itself, such as the operating system, utilities and drivers. Applications do user tasks.",
 "Why are SSDs used in laptops?": "SSDs have no moving parts, so they are faster, lighter, quieter and more robust if the laptop is dropped.",
 "What does OMR read?": "Optical mark recognition detects marks in set positions, such as multiple-choice answer sheets and lottery tickets.",
 "Which printer suits printing many school reports quickly?": "Laser printers print large volumes quickly and quietly with sharp text, and cost little per page.",
 "Why does a supermarket use barcode readers?": "Scanning is fast and accurate, and the system can update stock levels automatically as items are sold.",
 "Which is an output device?": "An actuator is an output device: it turns a signal from the computer into movement (motors, valves, pumps).",
 "What is RFID used for?": "Radio-frequency identification tags are read by radio waves without contact, for tracking stock, pets, passports and contactless payment.",
 "Why use magnetic tape for backups?": "Tape stores huge amounts of data cheaply. It is slow (serial access), which doesn't matter for backups.",
 "What does a compiler do?": "A compiler translates the whole program into machine code before it runs, producing an executable file. An interpreter translates line by line." },
"y10ict/networks": {
 "What does a router do?": "A router connects different networks (e.g. a home LAN to the internet) and directs data packets towards their destination.",
 "What is an intranet?": "An intranet is a private network that only an organisation's members can access, used for internal information.",
 "Which health problem is caused by repetitive typing?": "Repetitive strain injury (RSI) causes pain in the wrists and fingers. Reduce it with breaks, wrist rests and good posture.",
 "What is a WLAN?": "A wireless local area network connects devices in one site using Wi-Fi radio waves instead of cables.",
 "One disadvantage of cloud storage?": "You need an internet connection to reach your files, and you rely on the provider's security.",
 "How can eye strain be reduced?": "Take regular breaks, use anti-glare screens, adjust brightness and have good lighting.",
 "What is the difference between the internet and the WWW?": "The internet is the global network of connected computers; the World Wide Web is the collection of web pages accessed over it.",
 "Why do businesses use extranets?": "An extranet gives trusted outsiders, such as suppliers or customers, limited access to part of a company's intranet.",
 "What is a NIC?": "A network interface card lets a device connect to a network; it has a unique MAC address.",
 "What is phishing?": "Phishing uses fake emails pretending to be from banks or companies to trick people into revealing passwords or bank details.",
 "Why is a switch better than a hub?": "A switch sends data only to the device it is addressed to, reducing traffic and improving security. A hub sends it to every device.",
 "What is a benefit of web conferencing?": "People in different places can meet, share screens and edit documents live without travelling." },
"y10ict/safety": {
 "What is a firewall?": "A firewall monitors incoming and outgoing traffic and blocks anything that breaks its security rules.",
 "Which reduces the risk of tripping in an ICT room?": "Cable ducts (or cable covers) keep trailing wires off the floor, so people don't trip over them.",
 "What does encryption do?": "Encryption scrambles data so it cannot be understood without the decryption key, protecting it if it is intercepted.",
 "What is pharming?": "Pharming installs malicious code that redirects users to a fake website, even if they type the correct address.",
 "Which is a biometric method?": "Biometrics use unique body features: fingerprints, face, iris or voice.",
 "Which is a data protection principle?": "Data protection laws say personal data must be kept no longer than necessary, kept secure and used only for its stated purpose.",
 "Why consider audience when making a presentation for young children?": "Young children need simple language, large clear fonts, bright images and short text to understand and stay interested.",
 "What is netiquette?": "Netiquette is the set of rules for polite, respectful behaviour online, e.g. no writing in capitals (shouting) and no offensive posts.",
 "What is malware?": "Malware is malicious software, such as viruses, spyware and ransomware, designed to harm a computer or steal data.",
 "Why is it illegal to copy software without a licence?": "Software is protected by copyright, so copying it without permission breaks the law (software piracy).",
 "What is the risk of an overloaded socket?": "Too many plugs draw too much current, which makes the wiring overheat and can start a fire." },
"y10ict/lifecycle": {
 "What is the first stage of the systems life cycle?": "Analysis comes first: research the current system and the users' needs before designing anything.",
 "Which changeover switches straight to the new system?": "Direct changeover stops the old system and starts the new one immediately. It is fast but risky if the new system fails.",
 "What is a presence check?": "A presence check makes sure a required field has not been left blank.",
 "What is extreme data?": "Extreme data is at the edge of the valid range (e.g. 1 and 100 for a range 1–100). It should be accepted.",
 "Why might a pilot implementation be chosen?": "The new system is tried in one branch or department first, so problems are found before it goes everywhere.",
 "What does verification by double entry do?": "Data is typed twice and the two versions are compared; any difference shows a typing error.",
 "What does a questionnaire help with in analysis?": "Questionnaires collect views from many users quickly and anonymously.",
 "What is technical documentation for?": "Technical documentation explains how the system works (code, file structures, algorithms) so programmers can maintain and update it.",
 "Why is a check digit used?": "A check digit is calculated from the other digits; recalculating it catches errors such as swapped or mistyped digits in barcodes and ISBNs.",
 "What is computer modelling?": "A computer model simulates a real situation so you can test 'what if' scenarios safely and cheaply." },
"y10ict/spreadsheets": {
 "What must every formula start with?": "Every spreadsheet formula starts with = so the software knows to calculate it, e.g. =SUM(B2:B10).",
 "What does $A$1 mean?": "The dollar signs fix the column and the row, so the reference stays as A1 when the formula is copied (absolute reference).",
 "What does VLOOKUP do?": "VLOOKUP searches down the first column of a table for a value, then returns the value from a chosen column in the same row.",
 "What does =ROUND(3.456,1) return?": "ROUND to 1 decimal place: the second decimal is 5, so 3.456 rounds up to 3.5." },
"y10ict/databases": {
 "What is a record?": "A record is one row of a table, holding all the data about one item (e.g. one student).",
 "Which data type suits a date of birth?": "Date/time stores dates properly, so you can sort and calculate ages.",
 "Which HTML tag makes a link?": "The anchor tag <a href=\"…\"> makes a hyperlink.",
 "What is a primary key?": "A primary key is a field whose value is unique for every record, such as a student ID.",
 "Why use an external CSS stylesheet?": "One CSS file can style every page, so the site looks consistent and a single change updates all pages.",
 "What is house style?": "House style is an organisation's consistent set of fonts, colours, logos and layouts used on all documents.",
 "Which is the presentation layer of a web page?": "HTML is the content layer, CSS the presentation layer (how it looks) and JavaScript the behaviour layer.",
 "Why should images have alt text?": "Alt text is read by screen readers for visually impaired users and is shown if the image fails to load.",
 "What is a field?": "A field is one column in a table, holding one type of data (e.g. Surname).",
 "What does a Boolean field store?": "A Boolean field stores only two values: Yes/No or True/False.",
 "Why use relative file paths?": "Relative paths (e.g. images/logo.png) still work when the whole site folder is moved to a web server.",
 "What is a header in a document?": "A header is text (e.g. title or page number) that repeats at the top of every page." },
"y10psychology/development": {
 "Which stage begins at about age 11?": "Piaget's formal operational stage (11+): children can think abstractly and test hypotheses.",
 "What is a growth mindset?": "Dweck: people with a growth mindset believe ability can grow through effort and practice, so they keep going after mistakes.",
 "Which praise builds a growth mindset?": "Praising effort and strategy ('you worked hard') builds a growth mindset; praising intelligence ('you're so clever') can create a fixed mindset.",
 "What is the nature v nurture debate?": "The debate is about how much behaviour comes from genes (nature) versus environment and experience (nurture).",
 "A criticism of Piaget is that…": "Later studies, e.g. McGarrigle and Donaldson's 'naughty teddy', showed children could conserve earlier when tasks made sense to them.",
 "Why does Willingham criticise learning styles?": "Willingham found little evidence that teaching to a 'visual' or 'auditory' style improves learning; meaning and content matter more.",
 "At what stage do children understand conservation?": "In the concrete operational stage (about 7–11), children understand that quantity stays the same when shape changes.",
 "What is a longitudinal study?": "A longitudinal study follows the same people over a long period to see how they change.",
 "What does 'cultural bias' mean?": "If research uses one culture, the findings may not apply to people from other cultures.",
 "Why is it hard to separate nature and nurture?": "Genes and environment interact: genes affect how we respond to our environment, and environment affects how genes are expressed." },
"y10psychology/memory": {
 "Which is the first stage of memory?": "Memory has three processes: encoding (taking information in), storage and retrieval.",
 "Riding a bike is which type of memory?": "Procedural memory stores skills ('knowing how') that we do without conscious thought.",
 "What moves information from STM to LTM in the multi-store model?": "Atkinson and Shiffrin: rehearsal (repeating information) transfers it from short-term to long-term memory.",
 "What did Bartlett's 'War of the Ghosts' show?": "Participants changed the unfamiliar Native American story to fit their own culture, showing memory is reconstructive.",
 "What is anterograde amnesia?": "Anterograde amnesia is being unable to form new long-term memories after brain damage, as in the case of HM.",
 "A criticism of the multi-store model is…": "It is too simple: some information enters LTM without rehearsal, and STM and LTM are not single stores.",
 "Your 10th birthday party is which type of memory?": "Episodic memory stores personal events: what happened, when and where.",
 "What is a schema?": "A schema is a mental framework of expectations built from experience, which shapes how we remember new information.",
 "Why do lab memory studies lack ecological validity?": "Remembering word lists in a lab is not like everyday memory, so the results may not apply to real life.",
 "How long does information last in STM without rehearsal?": "Peterson and Peterson found short-term memory lasts about 18–30 seconds without rehearsal." },
"y10psychology/brain": {
 "Which lobe processes vision?": "The occipital lobe at the back of the brain processes visual information.",
 "What is the gap between neurons called?": "The synapse is the tiny gap between neurons, crossed by chemical neurotransmitters.",
 "Which part controls balance?": "The cerebellum, at the back below the cerebrum, coordinates balance and movement.",
 "What does Broca's area control?": "Broca's area, in the left frontal lobe, controls speech production. Damage causes slow, effortful speech.",
 "Which nervous system controls automatic functions like heart rate?": "The autonomic nervous system controls involuntary functions such as heart rate, breathing and digestion.",
 "What is lateralisation?": "Lateralisation means each hemisphere specialises in some functions; for example, language is mainly in the left hemisphere.",
 "Why is Phineas Gage's case limited evidence?": "It is a single case, records of his personality change are unreliable and may have been exaggerated, so it is hard to generalise.",
 "Damage to Wernicke's area most affects…": "Wernicke's area (left temporal lobe) is for understanding language; damage causes fluent but meaningless speech.",
 "What does the central nervous system include?": "The CNS is the brain and spinal cord. The peripheral nervous system is all the other nerves.",
 "What carries impulses away from the cell body?": "The axon carries electrical impulses away from the cell body towards the next neuron.",
 "Which brain scan shows activity, not just structure?": "fMRI shows which brain areas are active by detecting changes in blood flow. CT and MRI show structure.",
 "Why is the frontal lobe linked to decision-making?": "Damage to the frontal lobe (as in Phineas Gage) leads to impulsive behaviour and poor planning." },
"y10psychology/social": {
 "What is conformity?": "Conformity is changing your behaviour or beliefs to match a group.",
 "What is obedience?": "Obedience is following a direct order from an authority figure.",
 "In Milgram's original study, what percentage went to 450 volts?": "65% of participants gave what they thought was the maximum 450-volt shock, and all went to at least 300 volts.",
 "What is diffusion of responsibility?": "In a crowd, each person feels less responsible to help because they assume someone else will (bystander effect).",
 "What did Asch's study investigate?": "Asch tested conformity: participants judged line lengths after confederates gave obviously wrong answers. About 75% conformed at least once.",
 "What is deindividuation?": "Deindividuation is losing your sense of personal identity in a crowd or with anonymity, which can lead to antisocial behaviour.",
 "An ethical criticism of Milgram is…": "Participants were deceived about the shocks and many became very distressed, and they felt they couldn't easily withdraw.",
 "Why might people conform in Asch's study?": "Normative social influence: people wanted to fit in and avoid being rejected or laughed at, even when they knew the answer was wrong.",
 "What does a uniform tend to do to obedience?": "Bickman found that people obeyed more when the person giving orders wore a guard's uniform: uniforms signal authority.",
 "Why can Asch's study be criticised?": "The task was artificial (low ecological validity) and used only American male students in the 1950s, so it may not generalise.",
 "How could bystander intervention be increased?": "Picking out one person and asking them directly removes diffusion of responsibility.",
 "What is informational social influence?": "We conform because we believe others know better, especially when the situation is unclear." },
"y10psychology/problems": {
 "What does CBT stand for?": "Cognitive behavioural therapy helps people challenge negative thoughts and change unhelpful behaviour.",
 "What is tolerance in addiction?": "Tolerance means the body gets used to a substance, so more is needed to get the same effect.",
 "Which neurotransmitter is linked to depression?": "Low levels of serotonin are linked to depression (the biological explanation).",
 "What are withdrawal symptoms?": "Withdrawal symptoms are unpleasant physical and mental effects when someone stops taking a substance they depend on.",
 "How do SSRIs work?": "Selective serotonin reuptake inhibitors stop serotonin being reabsorbed, so more stays in the synapse.",
 "What is a classification system used for?": "Systems such as ICD-11 list symptoms so clinicians can diagnose conditions consistently.",
 "A weakness of drug therapy is…": "Drugs can have side effects, take weeks to work and may treat symptoms rather than the cause.",
 "Why does stigma matter?": "Stigma (negative attitudes) can make people feel ashamed and stop them seeking help.",
 "Which is a symptom of depression?": "Symptoms include low mood, loss of interest or pleasure in activities, sleep changes and tiredness.",
 "How does social learning explain addiction?": "Social learning theory: people imitate behaviour they see rewarded in role models, such as friends or celebrities.",
 "Why might CBT be more effective long term than drugs?": "CBT teaches skills that people keep using after therapy ends, so relapse rates can be lower.",
 "What does ICD stand for?": "The International Classification of Diseases is published by the World Health Organization." },
"y10psychology/methods": {
 "What is the independent variable?": "The independent variable (IV) is what the researcher changes; the dependent variable (DV) is what is measured.",
 "What is a null hypothesis?": "A null hypothesis predicts no effect or no difference, e.g. 'music will have no effect on memory'.",
 "Which sampling method selects whoever is available?": "Opportunity sampling uses whoever is available at the time. It is quick but may be biased.",
 "What is a repeated measures design?": "The same participants do every condition. It removes participant differences but can cause order effects.",
 "What does reliability mean?": "Results are reliable if the study gives consistent results when repeated.",
 "Why is informed consent important?": "Participants must understand what is involved and agree freely, which respects their rights.",
 "What is qualitative data?": "Qualitative data is descriptive, in words (e.g. interview answers); quantitative data is numbers.",
 "What is a field experiment?": "A field experiment manipulates an IV in a natural, real-life setting, giving higher ecological validity but less control.",
 "What is a confounding variable?": "A confounding variable is an uncontrolled variable that affects the DV, so you can't be sure the IV caused the result." },
"y8revmaths/angles": {
 "What do angles in a triangle add up to?": "The three interior angles of any triangle always add up to 180°. To find a missing angle: 180° − the other two.",
 "Vertically opposite angles are…": "When two straight lines cross, the angles opposite each other are equal." },
"y8revmaths/charts": {
 "Why must a stem-and-leaf diagram have a key?": "The key (e.g. 3 | 4 = 34) tells the reader what the stem and leaf mean; without it, 3 | 4 could be 34 or 3.4." },
"y8revmaths/compare": {
 "Which measures spread?": "The range (largest − smallest) measures spread. Mean, median and mode are averages.",
 "A line of best fit slopes downwards. What correlation?": "Downward slope: as one variable increases, the other decreases, which is negative correlation.",
 "Why is estimating far outside the data range unreliable?": "Extrapolation assumes the trend continues beyond the data, which may not be true." },
"y8revscience/nutrients": {
 "Which nutrient is mainly for growth and repair?": "Protein (meat, fish, eggs, beans) is used to build and repair cells, muscles and tissues.",
 "Which food is high in fibre?": "Wholemeal bread contains the outer layers of the grain, which are rich in fibre. Fibre keeps food moving through the gut and prevents constipation.",
 "Lack of vitamin C causes…": "Scurvy (bleeding gums, poor healing) is caused by a lack of vitamin C, found in citrus fruit and vegetables.",
 "What colour does iodine turn with starch?": "Iodine solution is orange-brown and turns blue-black if starch is present.",
 "Why do athletes eat more carbohydrates before a race?": "Carbohydrates are the body's main energy source, and extra is stored as glycogen in the muscles for the race.",
 "Why does a teenager need more energy than a 70-year-old?": "Teenagers are growing and are usually more active, so they need more energy.",
 "Which food test needs heating?": "Benedict's test for sugars: heat in a water bath; blue turns green, yellow, orange or brick-red if sugar is present.",
 "What problem can eating too much saturated fat cause?": "Saturated fat raises cholesterol, which can build up in arteries and lead to heart disease.",
 "Why do we need water?": "Water is needed for chemical reactions in cells, transporting substances in blood, and controlling body temperature.",
 "What does the ethanol (emulsion) test show?": "Shake the food with ethanol, then add water: a cloudy white emulsion shows fat is present.",
 "Why do fats make good energy stores?": "Fats store about twice as much energy per gram as carbohydrates, and they also insulate the body." },
"y8revscience/digestion": {
 "Where does digestion begin?": "Digestion begins in the mouth: teeth break food up (mechanical) and saliva contains amylase, which starts digesting starch.",
 "Which enzyme breaks down starch?": "Amylase breaks starch into sugars. It is made in the salivary glands, pancreas and small intestine.",
 "Where is most digested food absorbed?": "The small intestine is long and lined with villi, giving a huge surface area for absorbing food into the blood.",
 "What does the large intestine mainly absorb?": "The large intestine absorbs water from undigested food, forming faeces.",
 "What does protease break proteins into?": "Protease enzymes break proteins into amino acids, which the body uses to build new proteins.",
 "Why does the stomach contain hydrochloric acid?": "The acid kills harmful bacteria in food and gives the right acidic conditions for stomach protease (pepsin) to work.",
 "Why must food be digested before absorption?": "Large molecules like starch and protein are too big to pass through the gut wall, so they are broken into small, soluble ones.",
 "Why are villi only one cell thick?": "A thin wall gives a short diffusion distance, so digested food passes into the blood quickly.",
 "What is mechanical digestion?": "Mechanical digestion physically breaks food into smaller pieces (chewing, stomach churning), giving enzymes more surface to work on.",
 "What do gut bacteria do?": "Helpful bacteria in the large intestine digest some fibre, make vitamins such as vitamin K and help protect against harmful microbes.",
 "Lipase breaks fats into…": "Lipase enzymes break fats (lipids) into fatty acids and glycerol." },
"y8revscience/burning": {
 "Which gas is needed for burning?": "Combustion is a reaction with oxygen, about 21% of the air.",
 "What are the three sides of the fire triangle?": "A fire needs fuel, oxygen and heat. Remove any one side and the fire goes out.",
 "Burning is…": "Burning gives out energy as heat and light, so it is an exothermic reaction.",
 "What does limewater test for?": "Limewater turns milky (cloudy) when carbon dioxide is bubbled through it.",
 "Methane + oxygen → ?": "Complete combustion of a hydrocarbon fuel produces carbon dioxide and water: methane + oxygen → carbon dioxide + water.",
 "What is oxidation?": "Oxidation is when a substance gains oxygen, e.g. magnesium + oxygen → magnesium oxide. Burning and rusting are both oxidation.",
 "Iron rusts. Which word equation is right?": "Rusting needs both oxygen and water: iron + oxygen + water → hydrated iron(III) oxide (rust).",
 "What is a fuel?": "A fuel is a substance that releases useful energy when it burns, such as natural gas, petrol or wood.",
 "Which is a fossil fuel?": "Fossil fuels (coal, oil, natural gas) formed from ancient living things over millions of years. They are non-renewable.",
 "Why do metals gain mass when oxidised?": "Oxygen atoms from the air join onto the metal to make a metal oxide, so the product is heavier. Mass is conserved overall." },
"y8revscience/pollution": {
 "Which gas is mainly linked to global warming?": "Carbon dioxide from burning fossil fuels is the main greenhouse gas adding to global warming.",
 "How does a fire blanket put out a fire?": "The blanket smothers the fire and cuts off the oxygen, removing one side of the fire triangle.",
 "Which gas causes acid rain?": "Sulfur dioxide (and nitrogen oxides) dissolve in rainwater to form acids.",
 "What does a catalytic converter do?": "It changes harmful exhaust gases (carbon monoxide, nitrogen oxides) into less harmful ones such as carbon dioxide and nitrogen.",
 "What effect does acid rain have on limestone statues?": "Limestone is calcium carbonate, which reacts with acid, so the statues slowly dissolve and lose their detail.",
 "What are particulates?": "Particulates are tiny solid particles such as soot. They cause smog and lung problems and blacken buildings.",
 "Why does global warming raise sea levels?": "Ice on land (glaciers, ice sheets) melts into the sea, and seawater expands as it warms.",
 "Which action REDUCES greenhouse gas emissions?": "Renewable electricity (solar, wind) produces little or no carbon dioxide when generating power.",
 "How do firefighters stop forest fires spreading?": "Firebreaks are strips of cleared land, so the fire runs out of fuel.",
 "What is smog?": "Smog is a mixture of smoke and fog (or pollutants reacting in sunlight) that makes air harmful to breathe.",
 "Which greenhouse gas comes from cattle and rice fields?": "Methane is released by cattle digestion and flooded rice fields. It is a powerful greenhouse gas.",
 "How does removing sulfur from fuels help?": "Less sulfur in the fuel means less sulfur dioxide when it burns, so less acid rain.",
 "Why is a CO₂ extinguisher used on electrical fires?": "Carbon dioxide smothers the fire by removing oxygen and does not conduct electricity, unlike water." },
"y8revscience/particles": {
 "In which state are particles in neat rows?": "In a solid, particles are packed closely in a regular arrangement and vibrate about fixed positions.",
 "What is the change from gas to liquid?": "Condensing: gas particles lose energy, slow down and come closer together to form a liquid.",
 "Which state can flow AND be compressed?": "Gas particles are far apart and move randomly, so gases flow and can be squashed.",
 "What happens to the mass when ice melts?": "Melting is a physical change: no particles are added or lost, so the mass stays the same.",
 "Why does a smell spread across a room?": "Diffusion: gas particles move randomly and spread from where there are many to where there are few.",
 "Why does the temperature stay at 0 °C while ice melts?": "The energy taken in is used to break the forces holding particles in the solid, not to raise the temperature.",
 "Why do puddles dry faster on windy days?": "Wind carries away water particles that have evaporated, so more can escape from the surface.",
 "Why does a balloon shrink in the freezer?": "Cold gas particles move more slowly and hit the walls less often and less hard, so the pressure falls and the balloon shrinks.",
 "What is melting?": "Melting is the change from solid to liquid when particles gain enough energy to move past each other.",
 "What is the difference between boiling and evaporating?": "Boiling happens throughout the liquid at the boiling point; evaporation happens only at the surface, at any temperature.",
 "Why does sweating cool you down?": "Evaporating sweat takes heat energy from your skin, so your skin cools.",
 "Which has the strongest forces between particles?": "Solids have the strongest forces of attraction, which hold particles in fixed positions." },
"y8revscience/density": {
 "What are the units of density here?": "Density = mass ÷ volume. With mass in g and volume in cm³, density is in g/cm³.",
 "What is displacement used for?": "Lower an irregular object into water: the rise in water level (displaced volume) equals the object's volume.",
 "Which is densest?": "Lead is about 11.3 g/cm³, much denser than water (1 g/cm³), so it sinks.",
 "1 g/cm³ is equal to…": "1 cm³ = 0.000001 m³ and 1 g = 0.001 kg, so 1 g/cm³ = 1000 kg/m³ (the density of water)." },
"y8revscience/fluids": {
 "What is upthrust?": "Upthrust is the upward force a fluid (liquid or gas) pushes on an object in it.",
 "Why do submarines need thick hulls?": "Water pressure increases with depth, so deep down it pushes very hard on the hull.",
 "What happens to drag as a cyclist goes faster?": "The faster you move, the more air particles you hit each second, so drag (air resistance) increases.",
 "A boat floats. Which statement is true?": "A floating object is balanced: upthrust equals its weight.",
 "Why are cars streamlined?": "A smooth, streamlined shape lets air flow around it easily, reducing drag and saving fuel.",
 "Why do snowshoes stop you sinking?": "Pressure = force ÷ area. Snowshoes spread your weight over a larger area, so the pressure on the snow is lower.",
 "Why does a steel ship float even though steel is denser than water?": "Its hollow shape full of air displaces a huge volume of water, giving enough upthrust to balance its weight." },
"y8revenglish/punctuation": {
 "Which sentence uses commas correctly in a list?": "Commas separate items in a list, with 'and' before the last item (no comma needed before 'and' in British English).",
 "Which sentence uses a dash for a dramatic pause?": "The dash creates a pause before a surprising reveal: 'nobody was there'.",
 "Which is a comma splice (a mistake)?": "Two complete sentences joined only by a comma is a comma splice. Use a full stop, semicolon, dash or conjunction instead.",
 "Which fixes 'The test was hard I still passed'?": "A dash with 'but' correctly joins the two clauses and emphasises the contrast.",
 "Why might a writer use a dash instead of a comma?": "A dash gives a stronger, more dramatic pause than a comma, often for surprise or emphasis.",
 "Which uses a dash for an afterthought?": "The dash adds an extra comment at the end: '— probably.'",
 "Which sentence is punctuated correctly?": "Paired commas mark the extra information ('who is twelve') and the dash adds a dramatic ending." },
"y8revenglish/plurals": {
 "Which plural is spelled correctly?": "Some words ending in -o add -es: tomatoes, potatoes, heroes, echoes. (But pianos, photos.)",
 "Plural of 'church'?": "Words ending in -ch, -sh, -s, -x or -z add -es, so church becomes churches." },
"y8revhistory/nma": {
 "In which year was the New Model Army created?": "Parliament created the New Model Army in 1645 to replace its local armies with one national, professional force.",
 "Which side did the New Model Army fight for?": "It was Parliament's army (the Roundheads), fighting the Royalists (Cavaliers).",
 "What colour uniform did the New Model Army wear?": "Its soldiers wore red coats, an early version of the British 'redcoats'.",
 "How were officers promoted in the New Model Army?": "Officers were promoted for ability and skill, not noble birth, so it had experienced, capable leaders.",
 "Which battle in 1645 was a decisive New Model Army victory?": "At Naseby (June 1645) the New Model Army crushed the King's main army, effectively deciding the First Civil War.",
 "Why were soldiers paid regularly?": "Regular pay kept soldiers loyal and disciplined, so they did not loot or desert.",
 "Why did religion make the New Model Army strong?": "Many soldiers were Puritans who believed God was on their side, which gave them high morale.",
 "How was the New Model Army different from earlier armies?": "It was a full-time, national, professional army instead of part-time local militias led by nobles.",
 "Which was the MOST important reason for its success? A strong answer…": "Strong history answers explain several factors AND judge which was most important, with reasons.",
 "What rules did soldiers have to follow?": "Strict discipline: no swearing, drinking or looting, with harsh punishments for breaking rules.",
 "Why was it significant that it was a NATIONAL army?": "Soldiers would fight anywhere in the country, not just near home, so Parliament could use it wherever needed." },
"y8revhistory/trial": {
 "What was the 'Divine Right of Kings'?": "The belief that kings were chosen by God and answered only to God, not to Parliament or the people.",
 "What was Charles found guilty of?": "In January 1649 Charles was found guilty of treason against the people of England, as a 'tyrant, traitor, murderer and public enemy'.",
 "Where was Charles I executed?": "He was beheaded on 30 January 1649 outside the Banqueting House, Whitehall, London.",
 "What was Ship Money?": "Ship Money was a tax normally paid by coastal towns in wartime. Charles collected it across the whole country without Parliament's agreement.",
 "Why did Charles's religious changes anger Puritans?": "Charles and Archbishop Laud added decoration and ceremony to churches, which Puritans thought looked too Catholic.",
 "What happened in 1642 that helped start the war?": "Charles marched into Parliament with soldiers to arrest five MPs; they had escaped. Both sides then prepared for war.",
 "Why did the army decide Charles had to die?": "Even after defeat he kept plotting and started a Second Civil War (1648), so the army believed he could never be trusted.",
 "What was Pride's Purge (1648)?": "Colonel Pride's soldiers blocked MPs who wanted to keep negotiating with the King from entering Parliament.",
 "Why did Charles refuse to plead at his trial?": "He said no court had the authority to try a king, so the trial was illegal.",
 "What was the 'Rump Parliament'?": "The roughly 200 MPs left after Pride's Purge; they set up the court that tried the King.",
 "Why was the execution significant for the future?": "It showed that a monarch could be held accountable, which helped Parliament become more powerful than the Crown." },
"y8revhistory/cromwell": {
 "What title did Cromwell take in 1653?": "Cromwell became Lord Protector, ruling England, Scotland and Ireland until his death in 1658.",
 "What religious group did Cromwell belong to?": "Cromwell was a Puritan: he wanted a simple, strict form of Protestant worship.",
 "Which celebration did the Puritans ban?": "Puritans banned Christmas celebrations, which they saw as unbiblical and an excuse for excess.",
 "Why did Puritans close theatres?": "They saw plays as sinful, immoral and a distraction from God.",
 "What happened at Drogheda (1649)?": "Cromwell's army stormed Drogheda in Ireland and killed thousands of soldiers and many civilians, which is why many see him as a villain.",
 "What happened after Cromwell died in 1658?": "His son Richard could not control the army or Parliament, and Charles II was restored as king in 1660.",
 "Which is evidence Cromwell was a hero?": "He allowed Jews to return to England (1656) and gave religious freedom to many Protestant groups.",
 "Why is Cromwell's reputation still debated?": "Historians and the public judge him differently depending on which actions they focus on (e.g. Ireland or religious tolerance) and their own views.",
 "Why did many ordinary people dislike Puritan rule?": "Popular pleasures such as Christmas, theatres and many sports were banned or restricted.",
 "What was the Commonwealth?": "From 1649 to 1660 England was a republic with no monarch, called the Commonwealth (including the Protectorate).",
 "What did Cromwell do to Parliament in 1653?": "Cromwell marched soldiers into Parliament and dismissed the Rump Parliament.",
 "Why might Royalists see Cromwell as a villain?": "He helped execute the King, used the army to control Parliament and ruled almost like a military dictator." },
"y8revgeography/thames": {
 "Where is the source of the River Thames?": "The Thames rises in the Cotswold Hills near Kemble, Gloucestershire.",
 "Which sea does the Thames flow into?": "The Thames flows east into the North Sea through the Thames Estuary.",
 "About how long is the River Thames, in km?": "The Thames is about 346 km long, the longest river entirely in England.",
 "Which city does the Thames flow through just before its estuary?": "London grew on the Thames, just upstream of the estuary.",
 "What is the Thames Barrier for?": "Its gates close to stop high tides and storm surges from the North Sea flooding London.",
 "What is a tributary of the Thames?": "The River Kennet joins the Thames at Reading. Tributaries are smaller rivers that flow into a larger one.",
 "What is the Thames Estuary?": "The estuary is the wide, tidal mouth of the river where fresh water mixes with salt water.",
 "Why has the Thames been important for London's growth?": "It provided trade routes, transport, drinking water and later tourism.",
 "Why has the Thames become cleaner since 1957?": "In 1957 it was declared 'biologically dead'. Better sewage treatment and pollution laws have brought back fish and seals.",
 "Why might the Thames Barrier be closed more often in the future?": "Climate change brings rising sea levels and stronger storm surges, so high tides threaten London more often.",
 "Which direction does the Thames mostly flow?": "From the Cotswolds in the west, the Thames flows mainly east to the North Sea.",
 "From which point does the Thames become tidal?": "Teddington Lock marks the upper limit of the tide; below it, the river rises and falls with the tides.",
 "When did the Thames Barrier open?": "The Thames Barrier began operating in 1982 and was officially opened in 1984." },
"y8revgeography/watercycle": {
 "What powers the water cycle?": "The Sun's energy heats water so it evaporates, which drives the whole cycle.",
 "What is condensation?": "Water vapour cools and turns back into tiny water droplets, forming clouds.",
 "Rain, snow, sleet and hail are all forms of…": "Precipitation is any water falling from clouds to the ground.",
 "What is infiltration?": "Infiltration is water soaking into the soil from the surface.",
 "What is transpiration?": "Transpiration is water vapour lost from the leaves of plants.",
 "What is surface runoff?": "Surface runoff is water flowing over the ground into rivers, common when soil is saturated or impermeable.",
 "What is interception?": "Interception is when plants and trees catch rain before it reaches the ground, slowing it down.",
 "Why is the water cycle called a closed system?": "Water moves between stores but none is added or lost from the Earth, so the total amount stays the same.",
 "Why does cutting down forests increase flood risk?": "With fewer trees there is less interception and transpiration, so more rain reaches rivers, faster.",
 "What is evaporation?": "Evaporation is liquid water turning into water vapour, using heat from the Sun.",
 "What is groundwater?": "Groundwater is water stored in rocks underground (aquifers).",
 "What is percolation?": "Percolation is water moving down from the soil into the rock below." },
"y8revgeography/closer": {
 "Where a river starts is called the…": "The source is where a river begins, often in hills or mountains.",
 "Where two rivers meet is called a…": "A confluence is the point where two rivers join.",
 "What is a tributary?": "A tributary is a smaller river or stream that joins a larger one.",
 "Which valley shape is found in the upper course?": "In the upper course, vertical erosion cuts a narrow, steep V-shaped valley.",
 "What is a drainage basin?": "A drainage basin is the area of land drained by a river and its tributaries.",
 "What is a watershed?": "A watershed is the boundary of high land separating two drainage basins.",
 "How does the channel change downstream?": "Downstream, the channel gets wider and deeper as more water flows through it.",
 "Why does a river's discharge increase downstream?": "Tributaries add more water, so the volume of water flowing (discharge) increases.",
 "Why are rocks smaller and rounder near the mouth?": "Attrition: rocks knock against each other as they are carried, becoming smaller and rounder over long distances.",
 "Which feature is typical of the lower course?": "In the lower course the river is wide and slow, with a flat floodplain either side.",
 "Where does a river end?": "The mouth is where a river flows into a sea, lake or larger river.",
 "What is an estuary?": "An estuary is the tidal mouth of a river where fresh and salt water mix." },
"y8revgeography/shape": {
 "What is hydraulic action?": "Hydraulic action is the force of water pushing into cracks and breaking rock apart.",
 "What is attrition?": "Attrition is rocks carried by the river hitting each other, becoming smaller and rounder.",
 "When does a river deposit its load?": "A river drops its load when it slows down and loses energy, e.g. on the inside of a bend or at the mouth.",
 "Which landform is found in the upper course?": "Waterfalls form in the upper course where hard rock lies over soft rock.",
 "What is saltation?": "Saltation is pebbles and sand bouncing along the river bed.",
 "On a meander, where does erosion happen fastest?": "Water flows fastest on the outside of a bend, causing more erosion and forming a river cliff.",
 "What is a gorge?": "A gorge is a narrow, steep-sided valley left behind as a waterfall retreats upstream.",
 "Why does a waterfall form where hard rock lies over soft rock?": "The soft rock erodes faster, undercutting the hard rock until it collapses, so the waterfall moves back.",
 "How do levees form naturally?": "When the river floods, it drops its heaviest sediment first, right next to the channel. Repeated floods build raised banks.",
 "What is a slip-off slope?": "A slip-off slope is a gentle bank formed by deposition on the inside of a meander, where water is slower.",
 "What is abrasion?": "Abrasion is rocks carried by the river scraping and wearing away the bed and banks.",
 "What is traction?": "Traction is large boulders being rolled along the river bed.",
 "What are interlocking spurs?": "Interlocking spurs are hills that stick out on alternate sides of a V-shaped valley; the river winds around them." }
};
Object.keys(X).forEach(k => { const [s, t] = k.split("/"), S = U[s], T = S && (S.topics || []).find(z => z.id === t); if (!T) return;
  [].concat(T.tasks || [], T.pool || []).forEach(q => { if (q && !q.x && X[k][q.q]) q.x = X[k][q.q]; }); });
})(window.UK = window.UK || {});
